(self.webpackChunksite=self.webpackChunksite||[]).push([[4670],{6933:t=>{"use strict";t.exports=JSON.parse('{"slug":"pega-pega-the-game","title":"Pega-Pega: the game","authors":[{"name":"Ana Paula Crippa","contact":"anapaulacrippa","contactType":"github","contactUrl":"https://github.com/anapaulacrippa"},{"name":"Maria Eduarda Policante","contact":"poli404","contactType":"github","contactUrl":"https://github.com/poli404"}],"date":1752883200000,"readme":"<p>This game is all about following each other around and firing!!!\\nOnce you have your opponent on your sight, FIRE!</p>\\n<p>You can either play with one keyboard or using NetPlay WASM-4 support.</p>\\n<h2>Single keyboard</h2>\\n<ul>\\n<li>Player 1: arrow keys to move - shoots with button X;</li>\\n<li>Player 2: buttons S, F, E, and D to move - shoots with button A;</li>\\n</ul>\\n<h2>NetPlaying</h2>\\n<ul>\\n<li>Both players use the arrow keys on their own keyboards to move and shoot with their button X.</li>\\n</ul>"}')}}]);